package br.com.tapeteskalke.repository; import br.com.tapeteskalke.entity.ProdutoComponente; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface ProdutoComponenteRepository extends JpaRepository<ProdutoComponente,String> { @Query("select c from ProdutoComponente c join fetch c.materiaPrima where c.produto.id=:produtoId order by c.materiaPrima.nome") List<ProdutoComponente> fichaDe(@Param("produtoId")String produtoId); @Modifying @Query("delete from ProdutoComponente c where c.produto.id=:produtoId") void apagarFicha(@Param("produtoId")String produtoId); @Query("select distinct c.produto.id from ProdutoComponente c") Set<String> produtosComFicha(); }
